requests.preRequestScript:
function requestId(tag) {
  return "hopp_" + tag + "_" + Date.now() + "_" + Math.random().toString(36).slice(2, 9);
}
function readState(key) {
  const raw = pw.env.get(key);
  if (!raw) throw new Error("缺少前一步结果，请按集合中的顺序发送请求。");
  return JSON.parse(raw);
}
function currentUser() {
  const user = pw.env.get("user_id");
  if (!user) throw new Error("请先发送 01 获取题目。");
  return user;
}
pw.env.set("mr_payload", "");
const user = "llm_test_" + Date.now() + "_" + Math.random().toString(36).slice(2, 10);
pw.env.set("user_id", user);
pw.env.set("mr_profile", "");
pw.env.set("mr_profile_request", "");
const round = 1;
const difficulty = Number(pw.env.get("difficulty_level") || "2");
if (!Number.isInteger(difficulty) || difficulty < 1 || difficulty > 5) throw new Error("difficulty_level 应为 1 到 5。");
const pending = {user_id: user, round_no: round, request_id: requestId("start")};
pw.env.set("mr_round_counter", JSON.stringify(pending));
pw.env.set("mr_pending", JSON.stringify(pending));
pw.env.set("mr_current", "");
pw.env.set("mr_submit_ok", "");
pw.env.set("mr_payload", JSON.stringify({
  intent: "start_game", user_id: user, request_id: pending.request_id,
  round_no: round, difficulty_level: difficulty,
  scenario_topic: pw.env.get("scenario_topic") || "workplace"
}));

requests.testScript:
const r = typeof pw.response.body === "string" ? JSON.parse(pw.response.body) : pw.response.body;
const d = r && r.data;
const valid = pw.response.status === 200 && r.ok === true && d &&
  typeof d.scenario_id === "string" && d.scenario_id.length > 0 &&
  typeof d.question === "string" && d.question.length > 0 &&
  Array.isArray(d.options) && d.options.length === 4 &&
  d.options.every(x => typeof x === "string" && x.length > 0) &&
  Number.isInteger(d.difficulty) && d.difficulty >= 1 && d.difficulty <= 5;
pw.test("出题成功，包含题干、四个选项和有效难度", () => pw.expect(Boolean(valid)).toBe(true));
if (!valid) throw new Error("出题响应不完整，未保存本轮题目。请查看响应及 Make 执行记录。");
const pending = JSON.parse(pw.env.get("mr_pending"));
if (r.request_id !== pending.request_id) throw new Error("返回的 request_id 与本轮请求不一致。");
pw.env.set("mr_current", JSON.stringify({
  user_id: pending.user_id, round_no: pending.round_no,
  scenario_id: d.scenario_id, question: d.question,
  options: d.options, difficulty: d.difficulty, shown_at: Date.now()
}));

requests.preRequestScript:
function requestId(tag) {
  return "hopp_" + tag + "_" + Date.now() + "_" + Math.random().toString(36).slice(2, 9);
}
function readState(key) {
  const raw = pw.env.get(key);
  if (!raw) throw new Error("缺少前一步结果，请按集合中的顺序发送请求。");
  return JSON.parse(raw);
}
function currentUser() {
  const user = pw.env.get("user_id");
  if (!user) throw new Error("请先发送 01 获取题目。");
  return user;
}
pw.env.set("mr_payload", "");
const round = readState("mr_current");
if (round.user_id !== currentUser()) throw new Error("user_id 已改变，请重新获取题目。");
if (pw.env.get("mr_submit_ok") === round.user_id) throw new Error("本轮已提交成功，请发送 03 生成画像；下一轮从 01 开始。");
const choice = String(pw.env.get("choice") || "B").trim().toUpperCase();
if (!["A", "B", "C", "D"].includes(choice)) throw new Error("choice 只能是 A、B、C 或 D。");
const payload = {
  intent: "submit_choice", user_id: round.user_id, request_id: requestId("choice"),
  round_no: round.round_no, scenario_id: round.scenario_id,
  question: round.question, options: round.options, choice,
  decision_ms: Math.max(0, Date.now() - round.shown_at), difficulty_level: round.difficulty
};
pw.env.set("mr_submit_ok", "");
pw.env.set("mr_pending_submission", JSON.stringify(payload));
pw.env.set("mr_payload", JSON.stringify(payload));

requests.testScript:
const r = typeof pw.response.body === "string" ? JSON.parse(pw.response.body) : pw.response.body;
const valid = pw.response.status === 200 && r && r.ok === true && r.data && ["A", "B", "C", "D"].includes(r.data.predicted_choice);
pw.test("提交成功并返回有效预测", () => pw.expect(Boolean(valid)).toBe(true));
if (!valid) throw new Error("提交未成功，不继续画像测试。");
const sent = JSON.parse(pw.env.get("mr_pending_submission"));
if (r.request_id !== sent.request_id) throw new Error("提交响应 request_id 不一致。");
const correct = sent.choice === r.data.predicted_choice;
pw.test("计分与预测一致", () => {
  pw.expect(r.data.is_correct).toBe(correct);
  pw.expect(r.data.ai_score).toBe(correct ? 5 : 0);
  pw.expect(r.data.user_score).toBe(correct ? 0 : 5);
});
pw.env.set("mr_last_submission", JSON.stringify(sent));
pw.env.set("mr_submit_ok", sent.user_id);

requests.preRequestScript:
function requestId(tag) {
  return "hopp_" + tag + "_" + Date.now() + "_" + Math.random().toString(36).slice(2, 9);
}
function readState(key) {
  const raw = pw.env.get(key);
  if (!raw) throw new Error("缺少前一步结果，请按集合中的顺序发送请求。");
  return JSON.parse(raw);
}
function currentUser() {
  const user = pw.env.get("user_id");
  if (!user) throw new Error("请先发送 01 获取题目。");
  return user;
}
pw.env.set("mr_payload", "");
const user = currentUser();
if (pw.env.get("mr_submit_ok") !== user) throw new Error("请先成功提交当前用户的答案。");
pw.env.set("mr_profile", "");
pw.env.set("mr_payload", JSON.stringify({
  intent: "generate_profile", user_id: user, request_id: requestId("profile"),
  force_refresh: true
}));

pw.env.set("mr_profile_request", pw.env.get("mr_payload"));

requests.testScript:
const r = typeof pw.response.body === "string" ? JSON.parse(pw.response.body) : pw.response.body;
const d = r && r.data;
const valid = pw.response.status === 200 && r.ok === true && d &&
  typeof d.personality_type === "string" && typeof d.summary === "string" &&
  Array.isArray(d.traits) && d.traits.length === 3;
pw.test("返回画像及三个特征", () => pw.expect(Boolean(valid)).toBe(true));
if (!valid) throw new Error("画像返回不完整。");
const sent = JSON.parse(pw.env.get("mr_profile_request"));
if (r.request_id !== sent.request_id) throw new Error("画像响应 request_id 不一致。");
pw.env.set("mr_profile", JSON.stringify({user_id: pw.env.get("user_id"), data: d}));
